class Solution {
public:
    int maxKDivisibleComponents(int n, vector<vector<int>>& edges, vector<int>& values, int k) {
        vector<vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        int ans = 0;
        auto dfs = [&](auto& self, int u, int p) -> long long {
            long long total = values[u];
            for (int v : adj[u]) {
                if (v != p) total += self(self, v, u);
            }
            if (total % k == 0) {
                ans++;
                return 0;
            }
            return total % k;
        };
        dfs(dfs, 0, -1);
        return ans;
    }
};

class Solution {
    private int ans = 0;
    public int maxKDivisibleComponents(int n, int[][] edges, int[] values, int k) {
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }
        ans = 0;
        dfs(0, -1, adj, values, k);
        return ans;
    }
    private long dfs(int u, int p, List<Integer>[] adj, int[] values, int k) {
        long total = values[u];
        for (int v : adj[u]) {
            if (v != p) total += dfs(v, u, adj, values, k);
        }
        if (total % k == 0) {
            ans++;
            return 0;
        }
        return total % k;
    }
}

/**
 * @param {number} n
 * @param {number[][]} edges
 * @param {number[]} values
 * @param {number} k
 * @return {number}
 */
var maxKDivisibleComponents = function(n, edges, values, k) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    let ans = 0;
    function dfs(u, p) {
        let total = values[u];
        for (const v of adj[u]) {
            if (v !== p) total += dfs(v, u);
        }
        if (total % k === 0) {
            ans++;
            return 0;
        }
        return total % k;
    }
    dfs(0, -1);
    return ans;
};
